def READ_DSN():
    global DATASTREAM
    global PASS
    global STATUS
    global IPOLL
    global READ_SN_RESULT
    global DUMPDSN
    global UNIQUEEXITCODE
    PASS = 0
    READ_SN_RESULT[SIZE_READ_SN_RESULT - 1 - 3 - 128:SIZE_READ_SN_RESULT - 0] = hex2ba('000000000000000000000000000000000')
    fpc.irstop(fpc.IRPAUSE)
    fpc.drstop(fpc.DRPAUSE)
    fpc.irscanC(8, '0xf0')
    fpc.drscan(129, READ_SN_RESULT)
    fpc.wait( fpc.IDLE, 3, fpc.CYCLES, fpc.UNDEF )
    fpc.wait( fpc.UNDEF, 10, fpc.USEC, fpc.DRPAUSE)
    IPOLL = 100000 - -1
    while( IPOLL != 0 ):
        IPOLL += -1
        fpc.drscanCR(129, '0x000000000000000000000000000000000', READ_SN_RESULT)
        if ( (READ_SN_RESULT[SIZE_READ_SN_RESULT - 1 - 128]==0) ):
            IPOLL = 0
            PASS = 1
        if ( (PASS==0) ):
            fpc.irscanC(8, '0xf0')
            fpc.wait( fpc.IRPAUSE, 10, fpc.USEC, fpc.IRPAUSE)
        LABEL_SEPARATOR = 0
    # end IPOLL
    if ( (PASS==0) ):
        fpc.print(str("Failed to read DSN."))
        STATUS = -24
        UNIQUEEXITCODE = 32769
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
    DSN[SIZE_DSN - 1 - 127:SIZE_DSN - 0] = READ_SN_RESULT[SIZE_READ_SN_RESULT - 1 - 127:SIZE_READ_SN_RESULT - 0]
    if ( (DUMPDSN==1) ):
        fpc.print(str("==================================================================================="))
        ToExport = READ_SN_RESULT[SIZE_READ_SN_RESULT - 1 - 127:SIZE_READ_SN_RESULT - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "DSN", '0x'+ba2hex(ToExport), len( READ_SN_RESULT[SIZE_READ_SN_RESULT - 1 - 127:SIZE_READ_SN_RESULT - 0] ))
        fpc.print(str("==================================================================================="))
    DUMPDSN = 1
    READ_FSN_RESULT = READ_SN_RESULT
#end


def POLL_DEVICE_READY_DURING_EXIT():
    global DATASTREAM
    global PASS
    global STATUS
    global UNIQUEEXITCODE
    PASS = 0
    ILOOP_0 = 10000
    while( ILOOP_0 != 0 ):
        ILOOP_0 += -1
        fpc.irstop(fpc.IRPAUSE)
        fpc.drstop(fpc.DRPAUSE)
        fpc.irscanC(8, '0x0d')
        fpc.wait( fpc.IDLE, 1, fpc.CYCLES, fpc.UNDEF )
        fpc.wait( fpc.IDLE, 10, fpc.USEC, fpc.UNDEF )
        COMPARE_DIFF = SafeBitarray(8)
        fpc.drscanCR(8, '0x00', COMPARE_DIFF)
        if (  ( hex2ba('80') &  COMPARE_DIFF)  == (hex2ba('80') & hex2ba('00') ) ):
            PASS = 1
        else:
            PASS = 0
        if (PASS):
            ILOOP_0 = 0
        fpc.wait( fpc.IDLE, 1000, fpc.USEC, fpc.UNDEF )
    if ( (PASS==0) ):
        fpc.print(str("Instruction timed out. Device is busy."))
        STATUS = -32
        UNIQUEEXITCODE = 32818
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
    fpc.wait( fpc.RESET, 300000, fpc.USEC, fpc.UNDEF )
#end


def DO_EXIT():
    global DATASTREAM
    global PASS
    global STATUS
    global IPOLL
    global UNIQUEEXITCODE
    if ( (BPGMMODE==1) ):
        ISC_DISABLE_RESULT = SafeBitarray(32)
        ISC_DISABLE_RESULT[:] = 0
        SIZE_ISC_DISABLE_RESULT = 32
        PASS = 0
        fpc.irstop(fpc.IRPAUSE)
        fpc.drstop(fpc.DRPAUSE)
        fpc.irscanC(8, '0x0c')
        fpc.wait( fpc.IDLE, 3, fpc.CYCLES, fpc.UNDEF )
        fpc.wait( fpc.UNDEF, 10, fpc.USEC, fpc.DRPAUSE)
        IPOLL = 100000 - -1
        while( IPOLL != 0 ):
            IPOLL += -1
            fpc.drscanCR(32, '0x00000000', ISC_DISABLE_RESULT)
            if ( (ISC_DISABLE_RESULT[SIZE_ISC_DISABLE_RESULT - 1 - 31]==0) ):
                IPOLL = 0
                PASS = 1
            if ( (PASS==0) ):
                fpc.irscanC(8, '0x0c')
                fpc.wait( fpc.IRPAUSE, 10, fpc.USEC, fpc.IRPAUSE)
            LABEL_SEPARATOR = 0
        # end IPOLL
        if ( (PASS==0) ):
            fpc.print(str("Instruction timed out while disabling programming mode."))
            STATUS = -32
            UNIQUEEXITCODE = 32818
            BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
            ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
            ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
            fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        fpc.irstop(fpc.IRPAUSE)
        fpc.drstop(fpc.DRPAUSE)
        fpc.irscanC(8, '0x09')
        fpc.wait( fpc.IDLE, 1, fpc.CYCLES, fpc.UNDEF )
        fpc.wait( fpc.IDLE, 1000, fpc.USEC, fpc.UNDEF )
    READ_DSN()
    fpc.wait( fpc.RESET, 5, fpc.CYCLES, fpc.UNDEF )
    if ( (ACTIONTYPE!=ACTION_NONE) ):
        EXPORT_CERTIFICATES()
    POLL_DEVICE_READY_DURING_EXIT()
    sys.exit(STATUS)
#end


