def READ_SHARED_BUFFER():
    global DATASTREAM
    global PASS
    global STATUS
    global IPOLL
    global UNIQUEEXITCODE
    global IBLOCK
    IBLOCK = 0
    BLOCKBUFFER = SafeBitarray(136)
    BLOCKBUFFER[:] = 0
    SIZE_BLOCKBUFFER = 136
    IBLOCK = 0 - 1
    while( IBLOCK < (IBLOCKS-1) ):
        IBLOCK += 1
        PASS = 0
        SHARED_BUFFER_RESULT = SafeBitarray(136)
        SHARED_BUFFER_RESULT[:] = 0
        SIZE_SHARED_BUFFER_RESULT = 136
        BLOCKBUFFER[SIZE_BLOCKBUFFER - 1 - 8:SIZE_BLOCKBUFFER - 1] = int2ba(IBLOCK, length=8 - 1 +1 )
        fpc.irstop(fpc.IRPAUSE)
        fpc.drstop(fpc.DRPAUSE)
        fpc.irscanC(8, '0xf2')
        fpc.drscan(129, BLOCKBUFFER)
        fpc.wait( fpc.IDLE, 3, fpc.CYCLES, fpc.UNDEF )
        fpc.wait( fpc.UNDEF, 10, fpc.USEC, fpc.DRPAUSE)
        IPOLL = 100000 - -1
        while( IPOLL != 0 ):
            IPOLL += -1
            fpc.drscanCR(129, '0x000000000000000000000000000000000', SHARED_BUFFER_RESULT)
            if ( (SHARED_BUFFER_RESULT[SIZE_SHARED_BUFFER_RESULT - 1 - 128]==0) ):
                IPOLL = 0
                PASS = 1
            if ( (PASS==0) ):
                fpc.irscanC(8, '0xf2')
                fpc.wait( fpc.IRPAUSE, 10, fpc.USEC, fpc.IRPAUSE)
            LABEL_SEPARATOR = 0
        # end IPOLL
        if ( (PASS==0) ):
            fpc.print(str("Instruction timed out while reading design information."))
            STATUS = -32
            UNIQUEEXITCODE = 32818
            BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
            ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
            ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
            fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
            DO_EXIT()
        SHARED_BUFFER[SIZE_SHARED_BUFFER - 1 - ((128*IBLOCK)+127):SIZE_SHARED_BUFFER - (128*IBLOCK)] = SHARED_BUFFER_RESULT[SIZE_SHARED_BUFFER_RESULT - 1 - 127:SIZE_SHARED_BUFFER_RESULT - 0]
    # end IBLOCK
#end


