def VERIFY_IDCODE():
    global DATASTREAM
    global PASS
    global STATUS
    global IDREV
    global UNIQUEEXITCODE
    BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(ALGO_VERSION, length=15 - 0 +1 )
    ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
    ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
    fpc.export( "Algo_version", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
    fpc.wait( fpc.RESET, 5, fpc.CYCLES, fpc.UNDEF )
    PASS = 0
    fpc.irstop(fpc.IRPAUSE)
    fpc.drstop(fpc.DRPAUSE)
    fpc.irscanC(8, '0x0f')
    fpc.drscanC(32, '0x00000000')
    fpc.wait( fpc.IDLE, 1, fpc.CYCLES, fpc.UNDEF )
    fpc.drscanCR(32, '0x00000000', ID)
    if ( IDCODEVALUE == ID or (ID & IDMASK ) == (IDCODEVALUE & IDMASK ) ):
        PASS = 1
    else:
        PASS = 0
    PRINT_IDCODE()
    IDREV = ba2int(ID[SIZE_ID - 1 - 31:SIZE_ID - 28])
    if ( (PASS==0) ):
        fpc.print(str("Failed to verify IDCODE"))
        STATUS = 6
        UNIQUEEXITCODE = 32772
        if ( ( ( (ba2int(ID[SIZE_ID - 1 - 22:SIZE_ID - 12])==20) and (ba2int(IDCODEVALUE[SIZE_IDCODEVALUE - 1 - 22:SIZE_IDCODEVALUE - 12])==148)) or ( (ba2int(ID[SIZE_ID - 1 - 22:SIZE_ID - 12])==148) and (ba2int(IDCODEVALUE[SIZE_IDCODEVALUE - 1 - 22:SIZE_IDCODEVALUE - 12])==20))) ):
            UNIQUEEXITCODE = 32861
            fpc.print(str("NOTE: RTPF500{T|L|S} and RTPF500Z{T|L|S} programming bitstreams are not compatible."))
            fpc.print(str("Please ensure that the device selection in the Libero SoC project used to generate the programming file matches the device part number being programmed."))
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        DO_EXIT()
    if ( (PASS==1) ):
        pass
    POLL_DEVICE_READY()
#end


