def PROCESS_DATA():
    global DATASTREAM
    global PASS
    global DATAINDEX
    global COMPONENTNO
    global BLOCKNO
    global CURRNUMOFBLOCKS
    global COMPONENETSUPPORTSCERT
    global PERCENT_UPDATE
    global COMPTYPE
    TOTALNUMOFBLOCKS = 0
    TOTALCURRBLOCK = 0
    OWPKEYMODE = 0
    if ( (ACTIONTYPE!=ACTION_ERA) ):
        COMPONENTNO = (ICURCOMPONENTNO+1) - 1
        while( COMPONENTNO < ICURNUMOFCOMPONENTS ):
            COMPONENTNO += 1
            CURRNUMOFBLOCKS = ba2int(NUMOFBLOCKS[SIZE_NUMOFBLOCKS - 1 - ((COMPONENTNO*22)-1):SIZE_NUMOFBLOCKS - ((COMPONENTNO-1)*22)])
            TOTALNUMOFBLOCKS = (TOTALNUMOFBLOCKS+CURRNUMOFBLOCKS)
        # end COMPONENTNO
    COMPONENTNO = ICURCOMPONENTNO - 1
    while( COMPONENTNO < ICURNUMOFCOMPONENTS ):
        COMPONENTNO += 1
        fpc.irscanC(8, '0xee')
        fpc.drscan(128, DATASTREAM[SIZE_DATASTREAM - 1 - (DATAINDEX+127):SIZE_DATASTREAM - DATAINDEX])
        COMPONENETSUPPORTSCERT = 0
        CURRNUMOFBLOCKS = ba2int(NUMOFBLOCKS[SIZE_NUMOFBLOCKS - 1 - ((COMPONENTNO*22)-1):SIZE_NUMOFBLOCKS - ((COMPONENTNO-1)*22)])
        BLOCKNO = 1 - 1
        while( BLOCKNO < CURRNUMOFBLOCKS ):
            BLOCKNO += 1
            if ( (COMPONENTNO!=ICURCOMPONENTNO) ):
                TOTALCURRBLOCK = (TOTALCURRBLOCK+1)
            if ( (BLOCKNO==1) ):
                COMPONENETSUPPORTSCERT = ba2int(DATASTREAM[SIZE_DATASTREAM - 1 - (DATAINDEX+2721):SIZE_DATASTREAM - (DATAINDEX+2721)])
                COMPTYPE = ba2int(DATASTREAM[SIZE_DATASTREAM - 1 - (DATAINDEX+407):SIZE_DATASTREAM - (DATAINDEX+400)])
            if ( ( (BLOCKNO==1) and (COMPTYPE==COMP_OWP)) ):
                OWPKEYMODE = ba2int(DATASTREAM[SIZE_DATASTREAM - 1 - (DATAINDEX+415):SIZE_DATASTREAM - (DATAINDEX+408)])
                fpc.print(str("One-way Passcode (OWP) protocol is being used"))
            PASS = 0
            PROCESS_DATABLOCK()
            if ( ( ( (COMPONENTNO!=ICURCOMPONENTNO) and ((TOTALCURRBLOCK%1500)==0)) and (TOTALNUMOFBLOCKS!=0)) ):
                PERCENT_UPDATE = int((100*TOTALCURRBLOCK)/TOTALNUMOFBLOCKS)
                fpc.export( "PERCENT_DONE", str(PERCENT_UPDATE))
            DATAINDEX = (DATAINDEX+128)
        # end BLOCKNO
        if ( (DATA_SHIFT_RESULT[SIZE_DATA_SHIFT_RESULT - 1 - 1]==1) ):
            if ( ( ( ( ( (ACTIONTYPE!=ACTION_NONE) and (ACTIONTYPE!=ACTION_AUTH)) and (ACTIONTYPE!=ACTION_VER)) and ( (ACTIONTYPE==ACTION_PROG) and (RANPROGRAMMINGACTION==0))) and (COMPONENETSUPPORTSCERT==1)) ):
                READ_CERTIFICATE()
                if ( (COMPTYPE==COMP_FPGA) ):
                    ToExport = COMPONENTDIGEST
                    ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
                    fpc.export( "Fabric component bitstream digest", '0x'+ba2hex(ToExport), len( COMPONENTDIGEST ))
                if ( (COMPTYPE==COMP_SNVM) ):
                    ToExport = COMPONENTDIGEST
                    ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
                    fpc.export( "sNVM component bitstream digest", '0x'+ba2hex(ToExport), len( COMPONENTDIGEST ))
                if ( (COMPTYPE==COMP_OWP) ):
                    ToExport = COMPONENTDIGEST
                    ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
                    fpc.export( "OWP component bitstream digest", '0x'+ba2hex(ToExport), len( COMPONENTDIGEST ))
                if ( (COMPTYPE==COMP_ENVM) ):
                    ToExport = COMPONENTDIGEST
                    ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
                    fpc.export( "eNVM component bitstream digest", '0x'+ba2hex(ToExport), len( COMPONENTDIGEST ))
                LABEL_SEPARATOR = 0
            LABEL_SEPARATOR = 0
        LABEL_SEPARATOR = 0
    # end COMPONENTNO
#end


def SET_MODE():
    global DATASTREAM
    global PASS
    global STATUS
    global IPOLL
    global UNIQUEEXITCODE
    AUXLO_REG[SIZE_AUXLO_REG - 1 - 127:SIZE_AUXLO_REG - 0] = COFC_NONCE[SIZE_COFC_NONCE - 1 - 127:SIZE_COFC_NONCE - 0]
    LOAD_AUXLO()
    DATA_INIT_RESULT = SafeBitarray(8)
    DATA_INIT_RESULT[:] = 0
    SIZE_DATA_INIT_RESULT = 8
    PASS = 0
    fpc.irstop(fpc.IRPAUSE)
    fpc.drstop(fpc.DRPAUSE)
    fpc.irscanC(8, '0xae')
    fpc.drscan(8, PGMMODE)
    fpc.wait( fpc.IDLE, 3, fpc.CYCLES, fpc.UNDEF )
    fpc.wait( fpc.UNDEF, 10, fpc.USEC, fpc.DRPAUSE)
    IPOLL = 100000 - -1
    while( IPOLL != 0 ):
        IPOLL += -1
        fpc.drscanCR(8, '0x00', DATA_INIT_RESULT)
        if ( (DATA_INIT_RESULT[SIZE_DATA_INIT_RESULT - 1 - 7]==0) ):
            IPOLL = 0
            PASS = 1
        if ( (PASS==0) ):
            fpc.irscanC(8, '0xae')
            fpc.wait( fpc.IRPAUSE, 10, fpc.USEC, fpc.IRPAUSE)
        LABEL_SEPARATOR = 0
    # end IPOLL
    if ( (PASS==0) ):
        fpc.print(str("Instruction timed out while setting programming mode."))
        STATUS = -32
        UNIQUEEXITCODE = 32818
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        DO_EXIT()
    LABEL_SEPARATOR = 0
#end


