    fpc.wait( fpc.UNDEF, 10, fpc.USEC, fpc.DRPAUSE)
    IPOLL = 27777 - -1
    while( IPOLL != 0 ):
        IPOLL += -1
        fpc.drscanCR(8, '0x00', READ_CERT_RESULT)
        if ( (READ_CERT_RESULT[SIZE_READ_CERT_RESULT - 1 - 7]==0) ):
            IPOLL = 0
            PASS = 1
        if ( (PASS==0) ):
            fpc.irscanC(8, '0xa2')
            fpc.wait( fpc.IRPAUSE, 10, fpc.USEC, fpc.IRPAUSE)
        LABEL_SEPARATOR = 0
    # end IPOLL
    if ( (PASS==0) ):
        fpc.print(str("Instruction timed out while reading device certificate, device is busy."))
        STATUS = -32
        UNIQUEEXITCODE = 32818
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        DO_EXIT()
    if ( ( (ACTIONTYPE!=ACTION_PROG) and (ACTIONTYPE!=ACTION_ERA)) ):
        fpc.wait( fpc.IDLE, 1000, fpc.CYCLES, fpc.UNDEF )
    if ( (READ_CERT_RESULT[SIZE_READ_CERT_RESULT - 1 - 1]==0) ):
        IBLOCKS = 64
        READ_SHARED_BUFFER()
        DEVICE_CERTIFICATE[SIZE_DEVICE_CERTIFICATE - 1 - 8191:SIZE_DEVICE_CERTIFICATE - 0] = SHARED_BUFFER[SIZE_SHARED_BUFFER - 1 - 8191:SIZE_SHARED_BUFFER - 0]
