def DO_DISPLAY_CERTIFICATE():
    global DATASTREAM
    global PASS
    global STATUS
    global I
    global UNIQUEEXITCODE
    PASS = 0
    if ( ( (DEVICE_CERTIFICATE_READ==1) and (DEVICE_CERTIFICATE_VALIDATED==0)) ):
        fpc.print(str("Device certificate could not be validated due to internal error."))
        STATUS = -36
        UNIQUEEXITCODE = 33002
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        DO_EXIT()
    if ( ( (DEVICE_CERTIFICATE_READ==1) and (DEVICE_CERTIFICATE_VALIDATED==1)) ):
        fpc.print(str("Device certificate signature has been verified."))
        if ( (ACTIONTYPE==ACTION_READ_DEV_CERT) ):
            DEV_CERT_REV_BYTEORDER = SafeBitarray(8192)
            DEV_CERT_REV_BYTEORDER[:] = 0
            SIZE_DEV_CERT_REV_BYTEORDER = 8192
            I = 0 - 8
            while( I < 8183 ):
                I += 8
                DEV_CERT_REV_BYTEORDER[SIZE_DEV_CERT_REV_BYTEORDER - 1 - (I+7):SIZE_DEV_CERT_REV_BYTEORDER - I] = SHARED_BUFFER[SIZE_SHARED_BUFFER - 1 - (8191-I):SIZE_SHARED_BUFFER - (8184-I)]
            # end I
            ToExport = DEV_CERT_REV_BYTEORDER[SIZE_DEV_CERT_REV_BYTEORDER - 1 - 8191:SIZE_DEV_CERT_REV_BYTEORDER - 0]
            ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
            fpc.export( "DEVICE_CERTIFICATE(LSB->MSB)", '0x'+ba2hex(ToExport), len( DEV_CERT_REV_BYTEORDER[SIZE_DEV_CERT_REV_BYTEORDER - 1 - 8191:SIZE_DEV_CERT_REV_BYTEORDER - 0] ))
        LABEL_SEPARATOR = 0
    LABEL_SEPARATOR = 0
#end


