def DO_VERIFY():
    global DATASTREAM
    global DATAINDEX
    global ICURNUMOFCOMPONENTS
    global ICURCOMPONENTNO
    global RANPROGRAMMINGACTION
    if ( (RANPROGRAMMINGACTION==1) ):
        DO_UNLOCK_KEYS()
    fpc.print(str("Verifying FPGA Array and sNVM..."))
    PGMMODE[SIZE_PGMMODE - 1 - 7:SIZE_PGMMODE - 0] = hex2ba('02')
    SET_MODE()
    ICURCOMPONENTNO = 1
    ICURNUMOFCOMPONENTS = DATASIZE
    DATAINDEX = DATASTARTINDEX
    PROCESS_DATA()
    if ( (RANPROGRAMMINGACTION==1) ):
        RANPROGRAMMINGACTION = 0
    LABEL_SEPARATOR = 0
#end


