def DO_READ_UDV():
    global DATASTREAM
    global PASS
    global STATUS
    global IPOLL
    global UNIQUEEXITCODE
    READ_UDV_RESULT = SafeBitarray(32)
    READ_UDV_RESULT[:] = 0
    SIZE_READ_UDV_RESULT = 32
    PASS = 0
    fpc.irstop(fpc.IRPAUSE)
    fpc.drstop(fpc.DRPAUSE)
    fpc.irscanC(8, '0xcd')
    fpc.drscanC(32, '0x00000000')
    fpc.wait( fpc.IDLE, 3, fpc.CYCLES, fpc.UNDEF )
    fpc.wait( fpc.UNDEF, 10, fpc.USEC, fpc.DRPAUSE)
    IPOLL = 100000 - -1
    while( IPOLL != 0 ):
        IPOLL += -1
        fpc.drscanCR(32, '0x00000000', READ_UDV_RESULT)
        if ( (READ_UDV_RESULT[SIZE_READ_UDV_RESULT - 1 - 31]==0) ):
            IPOLL = 0
            PASS = 1
        if ( (PASS==0) ):
            fpc.irscanC(8, '0xcd')
            fpc.wait( fpc.IRPAUSE, 10, fpc.USEC, fpc.IRPAUSE)
        LABEL_SEPARATOR = 0
    # end IPOLL
    if ( (PASS==0) ):
        fpc.print(str("Instruction timed out while reading udv."))
        STATUS = -32
        UNIQUEEXITCODE = 32818
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        DO_EXIT()
    fpc.print(str("Die Firmware Version: ")+str(ba2int(READ_UDV_RESULT[SIZE_READ_UDV_RESULT - 1 - 15:SIZE_READ_UDV_RESULT - 8]))+str(".")+str(ba2int(READ_UDV_RESULT[SIZE_READ_UDV_RESULT - 1 - 7:SIZE_READ_UDV_RESULT - 0])))
    ToExport = READ_UDV_RESULT[SIZE_READ_UDV_RESULT - 1 - 31:SIZE_READ_UDV_RESULT - 0]
    ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
    fpc.export( "UDV", '0x'+ba2hex(ToExport), len( READ_UDV_RESULT[SIZE_READ_UDV_RESULT - 1 - 31:SIZE_READ_UDV_RESULT - 0] ))
#end


