def DO_VERIFY_DIGEST():
    global DATASTREAM
    global PASS
    global BUFF32
    global STATUS
    global IPOLL
    global IBLOCKS
    global UNIQUEEXITCODE
    CHECK_DIGESTS_RESULT = SafeBitarray(32)
    CHECK_DIGESTS_RESULT[:] = 0
    SIZE_CHECK_DIGESTS_RESULT = 32
    CHECK_DIGESTS_INPUT = SafeBitarray(32)
    CHECK_DIGESTS_INPUT[:] = 0
    SIZE_CHECK_DIGESTS_INPUT = 32
    fpc.irscanCRP(8, '0x0d', BUFF32, 32 - 1 - 7)
    if ( (BUFF32[SIZE_BUFF32 - 1 - 7]==1) ):
        DO_READ_DESIGN_INFO()
    FACTORY_DIGEST_ERROR = 0
    DIGEST_ERROR = 0
    DO_QUERY_SECURITY()
    if ( (SHARED_BUFFER[SIZE_SHARED_BUFFER - 1 - 10]==1) ):
        fpc.print(str("External digest check via JTAG/SPI Slave is disabled."))
        STATUS = -18
        UNIQUEEXITCODE = 32787
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        DO_EXIT()
    CHECK_DIGESTS_INPUT[SIZE_CHECK_DIGESTS_INPUT - 1 - 0] = 1
    PASS = 0
    fpc.irstop(fpc.IRPAUSE)
    fpc.drstop(fpc.DRPAUSE)
    fpc.irscanC(8, '0xd7')
    fpc.drscan(32, CHECK_DIGESTS_INPUT[SIZE_CHECK_DIGESTS_INPUT - 1 - 31:SIZE_CHECK_DIGESTS_INPUT - 0])
    fpc.wait( fpc.IDLE, 3, fpc.CYCLES, fpc.UNDEF )
    fpc.wait( fpc.UNDEF, 10, fpc.USEC, fpc.DRPAUSE)
    IPOLL = 100000 - -1
    while( IPOLL != 0 ):
        IPOLL += -1
        fpc.drscanCR(32, '0x00000000', CHECK_DIGESTS_RESULT)
        if ( (CHECK_DIGESTS_RESULT[SIZE_CHECK_DIGESTS_RESULT - 1 - 31]==0) ):
            IPOLL = 0
            PASS = 1
        if ( (PASS==0) ):
            fpc.irscanC(8, '0xd7')
            fpc.wait( fpc.IRPAUSE, 10, fpc.USEC, fpc.IRPAUSE)
        LABEL_SEPARATOR = 0
    # end IPOLL
    if ( (PASS==0) ):
        fpc.print(str("Instruction timed out while verifying digest."))
        STATUS = -32
        UNIQUEEXITCODE = 32818
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
