def DO_READ_DUMP_DIBS():
    global DATASTREAM
    global PASS
    global STATUS
    global IPOLL
    global I
    global IBLOCKS
    global UNIQUEEXITCODE
    PASS = 0
    READ_DIBS_RESULT = SafeBitarray(128)
    READ_DIBS_RESULT[:] = 0
    SIZE_READ_DIBS_RESULT = 128
    FACTORY_INTEGRITY_VALUE = SafeBitarray(256)
    FACTORY_INTEGRITY_VALUE[:] = 0
    SIZE_FACTORY_INTEGRITY_VALUE = 256
    FACTORY_INTEGRITY_VALUE[SIZE_FACTORY_INTEGRITY_VALUE - 1 - 255:SIZE_FACTORY_INTEGRITY_VALUE - 0] = hex2ba('4be48dc078655d410fcdce9bf440e55e2fab9525a27eb8f1e4b1db5c9d0caff6')
    fpc.irstop(fpc.IRPAUSE)
    fpc.drstop(fpc.DRPAUSE)
    fpc.irscanC(8, '0xe1')
    fpc.drscanC(128, '0x5c72316ace9e47de771c4f0105d870b4')
    fpc.wait( fpc.IDLE, 3, fpc.CYCLES, fpc.UNDEF )
    fpc.wait( fpc.UNDEF, 10, fpc.USEC, fpc.DRPAUSE)
    IPOLL = 100000 - -1
    while( IPOLL != 0 ):
        IPOLL += -1
        fpc.drscanCR(128, '0x5c72316ace9e47de771c4f0105d870b4', READ_DIBS_RESULT)
        if ( (READ_DIBS_RESULT[SIZE_READ_DIBS_RESULT - 1 - 127]==0) ):
            IPOLL = 0
            PASS = 1
        if ( (PASS==0) ):
            fpc.irscanC(8, '0xe1')
            fpc.wait( fpc.IRPAUSE, 10, fpc.USEC, fpc.IRPAUSE)
        LABEL_SEPARATOR = 0
    # end IPOLL
    if ( (PASS==0) ):
        fpc.print(str("Instruction timed out while reading device integrity bits."))
        STATUS = -32
        UNIQUEEXITCODE = 32818
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        DO_EXIT()
    if ( (READ_DIBS_RESULT[SIZE_READ_DIBS_RESULT - 1 - 0]==1) ):
        fpc.print(str("Error reading device integrity bits."))
        STATUS = 7
        UNIQUEEXITCODE = 33003
        BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] = int2ba(UNIQUEEXITCODE, length=15 - 0 +1 )
        ToExport = BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0]
        ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
        fpc.export( "ERROR_CODE", '0x'+ba2hex(ToExport), len( BUFF32[SIZE_BUFF32 - 1 - 15:SIZE_BUFF32 - 0] ))
        DO_EXIT()
    IBLOCKS = 11
    READ_SHARED_BUFFER()
    ToExport = FACTORY_INTEGRITY_VALUE[SIZE_FACTORY_INTEGRITY_VALUE - 1 - 255:SIZE_FACTORY_INTEGRITY_VALUE - 0]
    ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
    fpc.export( "Factory Integrity Bits", '0x'+ba2hex(ToExport), len( FACTORY_INTEGRITY_VALUE[SIZE_FACTORY_INTEGRITY_VALUE - 1 - 255:SIZE_FACTORY_INTEGRITY_VALUE - 0] ))
    ToExport = SHARED_BUFFER[SIZE_SHARED_BUFFER - 1 - 255:SIZE_SHARED_BUFFER - 0]
    ToExport[:0] = bitarray([0] * ((4 - len( ToExport ) % 4) % 4) )
    fpc.export( "Device Integrity Bits", '0x'+ba2hex(ToExport), len( SHARED_BUFFER[SIZE_SHARED_BUFFER - 1 - 255:SIZE_SHARED_BUFFER - 0] ))
    COUNTER = 0
    I = 0 - 32
    while( I < 224 ):
        I += 32
        if ( (ba2int(FACTORY_INTEGRITY_VALUE[SIZE_FACTORY_INTEGRITY_VALUE - 1 - (I+31):SIZE_FACTORY_INTEGRITY_VALUE - I])==ba2int(SHARED_BUFFER[SIZE_SHARED_BUFFER - 1 - (I+31):SIZE_SHARED_BUFFER - I])) ):
            COUNTER = (COUNTER+1)
        LABEL_SEPARATOR = 0
    # end I
    if ( (COUNTER==8) ):
        fpc.print(str("Device Integrity Status : PASS"))
    if ( (COUNTER!=8) ):
        fpc.print(str("Device Integrity Status : FAIL"))
        fpc.print(str("Please refer to Device Integrity Protection section of the PolarFire Family FPGA Security User Guide."))
    LABEL_SEPARATOR = 0
#end


