    fpc.wait( fpc.IDLE, 1, fpc.CYCLES, fpc.UNDEF )
    fpc.drscanCR(32, '0x00000000', BUFF32)
    if ( (ba2int(extend_to_32bits(BUFF32[SIZE_BUFF32 - 1 - 31:SIZE_BUFF32 - 0]) , signed=True )==-1) ):
        BUFF32[SIZE_BUFF32 - 1 - 31:SIZE_BUFF32 - 0] = hex2ba('00000000')
