    DUMP_DEBUG_INFO()
    READ_DSN()
    if ( (READ_SN_RESULT[SIZE_READ_SN_RESULT - 1 - 128]==1) ):
        DO_EXIT()
    DO_READ_TVS_MONITOR()
    DO_DUMP_SECURITY()
    DO_READ_DUMP_DIBS()
