def DO_CHECK_CYCLE_COUNT():
    global DATASTREAM
    CYCLECOUNT = 0
    MAXCYCLECOUNT = 500
    DO_READ_DEBUG_INFO()
    CYCLECOUNT = ba2int(SHARED_BUFFER[SIZE_SHARED_BUFFER - 1 - 495:SIZE_SHARED_BUFFER - 480])
    if ( ( (CYCLECOUNT>=(MAXCYCLECOUNT-50)) and (CYCLECOUNT<MAXCYCLECOUNT)) ):
        fpc.print(str("Info: You are ")+str((MAXCYCLECOUNT-CYCLECOUNT))+str(" cycles away from maximum programming cycle count of ")+str(MAXCYCLECOUNT)+str(" on this device. Refer to your device datasheet for more details."))
    if ( (CYCLECOUNT==MAXCYCLECOUNT) ):
        fpc.print(str("Info: You are in the last cycle to reach maximum programming cycle count of ")+str(MAXCYCLECOUNT)+str(" on this device. Refer to your device datasheet for more details."))
    if ( (CYCLECOUNT>MAXCYCLECOUNT) ):
        fpc.print(str("Warning: You have exceeded the maximum programming cycle count of ")+str(MAXCYCLECOUNT)+str(" on this device. Refer to your device datasheet for more details."))
    LABEL_SEPARATOR = 0
#end


